def even_desks(skills):
    m = len(skills) // 2
    total = sum(skills)
    reach = [0] * (m + 1)       # bit s of reach[c] is set when c traders can total s
    reach[0] = 1
    for x in skills:
        for c in range(m, 0, -1):
            reach[c] |= reach[c - 1] << x
    sums = reach[m]
    return min(abs(total - 2 * s) for s in range(total + 1) if sums >> s & 1)

