def even_desks(skills):
    total = sum(skills)
    reach = 1
    for x in skills:
        reach |= reach << x
    return min(abs(total - 2 * s) for s in range(total + 1) if reach >> s & 1)

def even_desks(skills):
    m = len(skills) // 2
    desks = [[], []]
    for x in sorted(skills, reverse=True):
        lighter = 0 if sum(desks[0]) <= sum(desks[1]) else 1
        if len(desks[lighter]) == m:
            lighter = 1 - lighter
        desks[lighter].append(x)
    return abs(sum(desks[0]) - sum(desks[1]))

from itertools import combinations

def even_desks(skills):
    m = len(skills) // 2
    total = sum(skills)
    return min(abs(total - 2 * sum(pick)) for pick in combinations(skills, m))
